
import type { CreditNoteLineInput } from './CreditNoteLineInput.js';
import type { MoneyValueInput } from './MoneyValueInput.js';

/** A correction against an issued invoice. Credit notes reduce what is owed; refunds return what was already collected. */ export type CreditNoteInput = { /** Identity frozen on the source invoice at issue. Later profile edits do not change this document. */ "buyer_tax_identity"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; "credit_note_id": string; "credit_note_lines": Array<CreditNoteLineInput>; /** Assigned at issue and stable from then on. Absent while the credit note is a draft. */ "credit_note_number"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "invoice_id": string; /** RFC3339 timestamp. Format: date-time. */ "issued_at"?: string | globalThis.Date; "latest_refund_status"?: "pending" | "in_transit" | "succeeded" | "failed" | "requires_action" | "canceled" | "partially_succeeded"; /** Free text shown on the credit note, up to 4096 characters. */ "memo"?: string; "merchant_id": string; "pending_refund_money": MoneyValueInput; /** Why the invoice is being corrected. Shown on the credit note document. */ "reason": "returned_goods" | "order_adjustment" | "billing_error" | "goodwill" | "other"; "refunded_money": MoneyValueInput; /** Identity frozen on the source invoice at issue. Later profile edits do not change this document. */ "seller_tax_identity"?: never; /** draft while the credit note is editable, issued once it is numbered and frozen, void once retired. */ "status": "draft" | "issued" | "void"; /** The face value of the credit note, the sum of its lines. */ "total_money": MoneyValueInput; /** Credit still available to allocate. Equals total_money at issue, falls as credit is applied, and rises again when an allocation is reversed. */ "unallocated_money": MoneyValueInput; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string | globalThis.Date; /** Current credit note version. Send this as expected_version when updating the draft. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "version"?: never; /** RFC3339 timestamp. Format: date-time. */ "voided_at"?: string | globalThis.Date; };
